<script setup>
/**
 * VideosView.vue - 非遗视听中心页面
 *
 * 功能:
 * - 页面标题 + 面包屑 + 描述
 * - 分类筛选标签: 全部/纪录片/教学/演出/访谈/宣传
 * - 视频卡片网格 (4/3/2/1列), 带封面+播放图标+时长+播放量
 * - 点击卡片弹出视频播放器弹窗 (模拟播放界面)
 * - 分页组件
 * - 骨架屏 + 空状态处理
 */
import { ref, computed, onMounted } from 'vue'
import { useStore } from 'vuex'
import SkeletonLoader from '@/components/SkeletonLoader.vue'
import EmptyState from '@/components/EmptyState.vue'

// Store
const store = useStore()

// ==================== 视频分类 ====================
const videoCategories = ref([
  '全部', '纪录片', '教学', '演出', '访谈', '宣传'
])

// 当前选中的分类
const currentCategory = ref('全部')

// 搜索关键词
const searchKeyword = ref('')

// ==================== 播放器弹窗状态 ====================
const selectedVideo = ref(null)

// ==================== 分页状态 ====================
const currentPage = ref(1)
const pageSize = 12
const totalCount = computed(() => store.state.videosTotal || 0)
const totalPages = computed(() => Math.ceil(totalCount.value / pageSize))

// ==================== 数据 ====================
const loading = computed(() => store.state.loading)
const videos = computed(() => store.state.videos)

// ==================== 计算属性 ====================

/**
 * 计算要显示的页码列表 (支持省略号)
 */
const displayedPages = computed(() => {
  const total = totalPages.value
  const current = currentPage.value
  const pages = []

  if (total <= 7) {
    for (let i = 1; i <= total; i++) pages.push(i)
  } else {
    pages.push(1)
    if (current > 3) pages.push('...')
    const start = Math.max(2, current - 1)
    const end = Math.min(total - 1, current + 1)
    for (let i = start; i <= end; i++) pages.push(i)
    if (current < total - 2) pages.push('...')
    pages.push(total)
  }

  return pages
})

// ==================== 方法 ====================

/**
 * 选择分类标签
 * @param {string} cat - 分类名称
 */
const selectCategory = (cat) => {
  if (cat === currentCategory.value) return
  currentCategory.value = cat
  currentPage.value = 1
  fetchData()
}

/**
 * 处理搜索
 */
const handleSearch = () => {
  currentPage.value = 1
  fetchData()
}

/**
 * 根据当前分类和页码获取视频数据
 */
const fetchData = async () => {
  const params = {
    page: currentPage.value,
    limit: pageSize
  }
  // 仅非"全部"时添加分类参数
  if (currentCategory.value !== '全部') {
    params.category = currentCategory.value
  }
  // 添加搜索参数
  if (searchKeyword.value.trim()) {
    params.search = searchKeyword.value.trim()
  }

  try {
    await store.dispatch('fetchVideos', params)
  } catch (err) {
    console.error('获取视频列表失败:', err)
  }
}

/**
 * 跳转到指定页码
 * @param {number} page - 目标页码
 */
const goToPage = (page) => {
  if (page < 1 || page > totalPages.value) return
  currentPage.value = page
  fetchData()
  window.scrollTo({ top: 0, behavior: 'smooth' })
}

/**
 * 打开视频播放器弹窗
 * @param {Object} video - 视频数据对象
 */
const openVideoPlayer = (video) => {
  selectedVideo.value = video
  // 禁止背景滚动
  document.body.style.overflow = 'hidden'
}

/**
 * 关闭视频播放器弹窗
 */
const closeVideoPlayer = () => {
  selectedVideo.value = null
  // 恢复背景滚动
  document.body.style.overflow = ''
}

/**
 * 播放视频 (模拟)
 */
const playVideo = () => {
  // 实际项目中这里会调用视频播放器SDK
  alert('视频播放功能开发中...')
}

/**
 * 格式化播放量为可读形式 (如 1200 -> 1.2k)
 * @param {number} views - 播放量
 * @returns {string} 格式化后的字符串
 */
const formatViews = (views) => {
  if (!views) return '0'
  if (views >= 10000) {
    return (views / 10000).toFixed(1) + 'w'
  }
  if (views >= 1000) {
    return (views / 1000).toFixed(1) + 'k'
  }
  return views.toString()
}

/**
 * 格式化日期
 * @param {string} dateStr - 日期字符串
 * @returns {string} 格式化后的日期
 */
const formatDate = (dateStr) => {
  if (!dateStr) return ''
  const date = new Date(dateStr)
  return `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
}

// ==================== 生命周期 ====================
onMounted(async () => {
  // 获取视频分类列表 (如store中有)
  if (store.state.videoCategories && store.state.videoCategories.length > 0) {
    videoCategories.value = ['全部', ...store.state.videoCategories]
  }

  // 获取视频数据
  await fetchData()
})
</script>

